'use strict';
let activeFable=null,fableNode='start';
const fables=[
 {id:'gate',title:'Darwaaze ke us paar',description:'Ek room, ek gatekeeper, aur apni jagah chunne ke teen raaste.',note:'Being underestimated. Original fiction inspired by a theme in our Ashtavakra reflection; not an ancient episode or translation.',art:'gate',nodes:{start:{text:'Ek chhoti si library ke darwaaze par tumhare saath ek musafir khada hai. Andar kahaaniyan chal rahi hain. Gatekeeper kehta hai, “Shayad yeh room tumhare liye nahi.” Musafir tumhari taraf dekhta hai. “Ab?”',choices:[['Apni baat rakhte hain','speak'],['Kisi saathi ko bulaate hain','company'],['Pehle courtyard mein rukte hain','pause']]},speak:{text:'Musafir kehta hai, “Humein ek kahaani sunni hai. Hum bhi ek sawal laaye hain.” Gatekeeper apni kitaab band karta hai. Room ka jawab abhi pata nahi—par musafir ki baat hawa mein aa gayi hai.',choices:[['Sawal kya hai?','question'],['Yahin kahaani rok dein','end-speak']]},question:{text:'Musafir dheere se poochhta hai: “Kya meri jagah sirf tab hogi jab main khud ko prove karun?” Courtyard mein baitha ek bachcha kursi aage khiska deta hai. “Yahan ek seat hai.”',end:true,reflection:'Kisi ki pehli rai aapki poori pehchaan nahi. Apni jagah ke liye exceptional hona zaroori nahi.'},company:{text:'Tum ek purane dost ko awaaz dete ho. Woh darwaaza todne nahi aata—bas paas khada hota hai. “Saath chalna hai, ya yahin baithna hai?”',choices:[['Saath mein room try karein','end-company'],['Aaj courtyard hi kaafi hai','end-pause']]},pause:{text:'Courtyard mein neem ki chhaon hai. Musafir apna bag neeche rakhta hai. Aaj andar jaana hi kahaani ka eklauta ending nahi.',choices:[['Thodi der baithte hain','end-pause'],['Kal ka darwaaza kal dekhenge','end-pause']]},'end-speak':{text:'Tum apni baat rakh kar ruk jaate ho. Room ka faisla abhi baaki hai. Tumhari kahaani us faisle se badi reh sakti hai.',end:true,reflection:'Apni baat kehna aur kisi ka approval milna alag cheezein hain.'},'end-company':{text:'Do log ek saath darwaaze tak aate hain. Is baar musafir ko sab words akele nahi dhoondhne. Kahaani yahan rukti hai; aage ka raasta khula hai.',end:true,reflection:'Saath maangna apni awaaz kho dena nahi hai.'},'end-pause':{text:'Musafir ek patta uthata hai aur kitaab mein rakh leta hai. “Yeh din sirf ek gatekeeper ki baat nahi tha,” woh kehta hai. Door se kahaani ki halki si awaaz aa rahi hai.',end:true,reflection:'Kisi jagah se aaj peeche hatna, apni value se peeche hatna nahi.'}}},
 {id:'cup',title:'Tedha sa cup',description:'Ek potter ki dukaan mein ek unfinished cheez tumhara intezaar kar rahi hai.',note:'Original interactive fiction about imperfection. No score or personality interpretation.',art:'sanctuary',nodes:{start:{text:'Baarish ke baad ek potter ki dukaan khuli hai. Shelf par ek cup thoda tedha rakha hai. Potter poochhta hai, “Iska kya karein?”',choices:[['Tedha rehne dete hain','keep'],['Thoda sa milkar badalte hain','change'],['Aaj shelf par rehne dete hain','wait']]},keep:{text:'Potter cup mein ek chhota phool rakhta hai. “Ab?” Woh muskurata hai, par tumhe pasand aana zaroori nahi.',choices:[['Phool ko window ke paas rakhein','end-keep'],['Iska naam rakhte hain','name']]},name:{text:'Tum ek naam chunte ho—“Abhi Itna.” Potter chalk se shelf par likh deta hai. Cup ko apni shape explain nahi karni padti.',end:true,reflection:'Kya koi cheez aaj unfinished reh kar bhi apni jagah rakh sakti hai?'},change:{text:'Potter clay aur paani paas rakhta hai. “Poora cup dobara?” woh poochhta hai. Tum sirf handle ki taraf ishara kar sakte ho.',choices:[['Bas handle','end-change'],['Aaj dekhna hi kaafi','end-wait']]},wait:{text:'Dukaan mein ek khaali jagah hai. Potter cup ko wahan rakhta hai. “Kuch decisions ko mitti ki tarah thoda waqt chahiye.”',choices:[['Kal ke liye jagah chhod dein','end-wait'],['Abhi chai peete hain','end-wait']]},'end-keep':{text:'Window par cup, cup mein phool, phool ke neeche baarish ki ek boond. Dukaan apne aap mein ek chhota sa scene ban jaati hai.',end:true,reflection:'Kisi cheez ko accept karna, sab kuch waise hi rakhne ka lifelong promise nahi.'},'end-change':{text:'Handle ka ek chhota hissa badalta hai. Baaki cup apni kahaani rakhta hai. Potter shelf par jagah banata hai.',end:true,reflection:'Badlav ka size tumhari available energy ke hisaab se ho sakta hai.'},'end-wait':{text:'Cup apni shelf par hai. Chai ek doosre cup mein aa jaati hai. Aaj har unfinished cheez ko finish karna zaroori nahi tha.',end:true,reflection:'Rukna bhi ek valid choice ho sakti hai.'}}},
 {id:'boat',title:'Teen kinaare',description:'Ek chhoti boat, ek folded map, aur bina race ke ek safar.',note:'Original interactive fable about choice and uncertainty. Loosely uses a journey metaphor; not a historical text.',art:'waves',nodes:{start:{text:'Tum ek chhoti boat mein ek traveller ke saath ho. Map par teen kinaare hain: ek par roshni, ek par ped, aur ek par ek ghar. Koi timer nahi chal raha.',choices:[['Roshni ki taraf','light'],['Pedon ke paas','trees'],['Ghar ki taraf','house']]},light:{text:'Roshni ek lantern se aa rahi hai. Paas pahunchne par poora safar saaf nahi hota—bas agla patthar dikhne lagta hai.',choices:[['Agla patthar dekhein','end-light'],['Boat se hi roshni dekhein','end-trees']]},trees:{text:'Pedon ke paas paani dheema hai. Traveller map fold karta hai. “Pehle kya choose kiya tha?” tum poochhte ho. “Abhi yahan hain,” woh kehta hai.',choices:[['Thodi der sunte hain','end-trees'],['Map dobara kholein','end-light']]},house:{text:'Ghar ke bahar do kursiyan hain. Ek par koi baitha hai jo poochhta hai, “Advice chahiye ya company?”',choices:[['Bas company','end-house'],['Map saath dekhenge','end-light']]},'end-light':{text:'Map par tum ek chhota nishaan lagate ho: “Yahan tak dekha.” Safar ka poora jawab abhi nahi, par ek actual jagah ka naam hai.',end:true,reflection:'Kya tumhe abhi poora plan chahiye, ya ek chhoti clarity kaafi ho sakti hai?'},'end-trees':{text:'Boat paani par halki si hilti hai. Koi race jeeti nahi gayi. Kahaani ko ek shaant pause milta hai.',end:true,reflection:'Har pause ko productive banana zaroori nahi.'},'end-house':{text:'Tum doosri kursi par baithte ho. Map band reh sakta hai. Do log shaam ke rang dekhte hain.',end:true,reflection:'Saath ke liye har baar ek problem solve karna zaroori nahi.'}}}
];
function storyPlayroom(){return `<h1>Thodi kahaani.<br>Thodi apni marzi.</h1><p class="sub">Chhoti interactive stories. Koi score, streak, ya “right” ending nahi.${hi('Bas explore karo. Meaning dhoondhna bhi optional hai.')}</p>${fables.map(f=>`<a class="story-card" href="#play/${f.id}"><div class="story-art">${art(f.art)}</div><div class="story-copy"><p class="small">Original interactive fiction · 2–3 choices</p><h3>${esc(f.title)}</h3><p>${esc(f.description)}</p><span class="read-label">Kahaani mein chalein</span></div></a>`).join('')}`}
function playFable(id){const f=fables.find(f=>f.id===id);if(!f)return notFound();if(activeFable!==id){activeFable=id;fableNode='start'}const node=f.nodes[fableNode]||f.nodes.start;return `${button('‹ Story room','go-play','back')}<div class="story-art" style="border-radius:23px">${art(f.art)}</div><p class="greeting" style="margin-top:20px">Original interactive fiction</p><h1>${esc(f.title)}</h1><p class="small">${esc(f.note)}</p><div class="fable-text">${esc(node.text)}</div>${node.choices?node.choices.map(([label,next])=>`<button class="story-choice" data-fable-next="${next}">${esc(label)}<span>›</span></button>`).join(''):`<p class="tag">Aaj ka ek ending. Tumhari personality ka result nahi.</p><details><summary>Ek reflection, agar chaaho</summary><p class="sub">${esc(node.reflection)}</p></details>${button('Doosra raasta try karein','restart-fable','secondary')}${button('Bas kahaani enjoy ki · back to stories','go-play','text-btn')}`}`}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.fableNext){const f=fables.find(f=>f.id===activeFable);if(f?.nodes[el.dataset.fableNext]){fableNode=el.dataset.fableNext;render()}return}if(el.dataset.action==='restart-fable'){fableNode='start';render()}if(el.dataset.action==='log-fable'){beginCheckin();logDraft.activity='story';render()}});
